package com.example.proyectolp.repository;
import com.example.proyectolp.model.DailyMission;import com.example.proyectolp.service.SupabaseService;import java.time.LocalDate;import java.util.*;
public class DailyMissionRepository {private final SupabaseService db;public DailyMissionRepository(SupabaseService d){db=d;}public List<DailyMission> list(LocalDate date)throws Exception{return db.getList("daily_missions?select=*&mission_date=eq."+date+"&order=id",DailyMission.class);}public void create(LocalDate date,String code,String description,int target,int xp)throws Exception{db.insertIgnore("daily_missions?on_conflict=user_id,mission_date,code",Map.of("mission_date",date,"code",code,"description",description,"target",target,"xp_reward",xp),DailyMission.class);}public void progress(LocalDate date,String code,int amount)throws Exception{for(DailyMission m:list(date))if(m.code.equals(code)&&!m.completed){int p=Math.min(m.target,m.progress+amount);db.patch("daily_missions?id=eq."+m.id,Map.of("progress",p,"completed",p>=m.target),"return=minimal");}}}
